package mutuelle_backend;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class AuthIntegrationTests { @Autowired MockMvc mvc; @Test void rejectsInvalidLogin() throws Exception {mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"deces\",\"password\":\"wrong\"}")).andExpect(status().isUnauthorized());} @Test void loginAndAuthorization() throws Exception {String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"deces\",\"password\":\"1234\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.section").value("DECES")).andReturn().getResponse().getContentAsString();String token=body.replaceAll(".*\\\"token\\\":\\\"([^\\\"]+)\\\".*","$1");mvc.perform(get("/api/sections/deces/dashboard").header("Authorization","Bearer "+token)).andExpect(status().isOk());mvc.perform(get("/api/adherents").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());} @Test void protectsApi() throws Exception {mvc.perform(get("/api/adherents")).andExpect(status().isUnauthorized());} }
